"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["42479"],{59854(e){e.exports=JSON.parse('{"id":"FIN-1301","slug":"microfinance","term":"Microfinance","also_known_as":[],"difficulty":"Advanced","definition":"Microfinance is the provision of small loans, savings accounts, insurance and other financial services to low-income people and small businesses who lack access to traditional banking.","explanation":["Many people in developing countries cannot get loans from banks because they lack collateral, credit histories or steady incomes, and the loan amounts they need are too small to be profitable for traditional lenders. Microfinance institutions fill this gap.","A key innovation was group lending, in which small groups of borrowers support and guarantee each other\'s loans, reducing the need for collateral. The Grameen Bank in Bangladesh, founded by Muhammad Yunus, pioneered this approach; Yunus and the bank received the Nobel Peace Prize in 2006.","For example, a woman running a small market stall might borrow a small sum to buy more stock, repaying it in weekly instalments from her increased sales.","Microfinance has helped millions of people start or grow small businesses and manage financial emergencies. However, research has found its effects on poverty to be more modest than early supporters hoped, and some microlenders have charged high interest rates or caused over-indebtedness. Mobile money has expanded access to financial services further."],"note":"","total":1500,"prev":{"slug":"microeconomics","term":"Microeconomics"},"next":{"slug":"mid-cap-stock","term":"Mid-Cap Stock"}}')}}]);